        if (value instanceof String) {
            String tag = (String) value;
            if (!tag.contains(":")) {
                context.report(ISSUE, context.getLocation(tagArg),
                        "Wake lock tags should be in the format `package:tag` or `package:component`.");
            }
        }
    }
}
